<script setup lang="ts">
import { ref } from 'vue';import { onShow } from '@dcloudio/uni-app';import { api } from '../../api/http';import { useSessionStore } from '../../stores/session'
const items=ref<any[]>([]),plan=ref(''),submitting=ref(false);const store=useSessionStore();onShow(async()=>{if(!store.session)await store.load();try{items.value=await api.renovations()}catch{}})
const statusText=(s:string)=>({DEPOSIT_UNPAID:'未交押金',DEPOSIT_PAID:'已交押金',COMMITMENT_SIGNED:'已签承诺书',COMPLETED:'已办结'} as any)[s]||s
async function submit(){if(plan.value.trim().length<2)return uni.showToast({title:'请填写装修方案',icon:'none'});submitting.value=true;try{await api.createRenovation({applicantName:store.session?.displayName||'',phone:store.session?.phone||'',plan:plan.value.trim()});plan.value='';items.value=await api.renovations();uni.showToast({title:'登记成功',icon:'success'})}finally{submitting.value=false}}
</script>
<template><view class="page renovation-page"><view class="notice"><view>📣 温馨提示</view><text>1. 装修需缴纳电梯装修押金 2000 元。</text><text>2. 线上提交登记，押金与承诺书仍需线下办理。</text><text>3. 管理员处理后状态会同步到本页面。</text></view><view class="form card"><textarea v-model="plan" maxlength="255" placeholder="请填写装修项目、预计工期等方案"/><button class="primary-btn" :loading="submitting" @click="submit">提交装修登记</button></view><view class="section-title"><text>我的装修记录</text><text>{{ items.length }} 条</text></view><view v-for="item in items" :key="item.id" class="record card"><view><strong>{{ item.plan }}</strong><text>{{ item.createdAt.replace('T',' ').slice(0,16) }}</text></view><text class="status OVERDUE">{{ statusText(item.status) }}</text></view><view v-if="!items.length" class="empty">暂无装修登记记录</view></view></template>
<style lang="scss" scoped>.renovation-page{max-width:920rpx;margin:auto}.notice{background:linear-gradient(135deg,#fff1f1,#ffe7e7);border:1rpx solid #ffd2d2;border-radius:22rpx;padding:27rpx;color:#ed3535;line-height:1.8}.notice view{font-size:30rpx;font-weight:900;margin-bottom:9rpx}.notice text{display:block;font-size:23rpx;font-weight:600}.form{margin-top:22rpx;padding:22rpx}.form textarea{width:100%;height:160rpx;background:#f6f8fc;border-radius:14rpx;padding:18rpx}.primary-btn{margin-top:18rpx}.record{padding:24rpx;display:flex;align-items:center;justify-content:space-between;margin-bottom:14rpx}.record strong,.record view>text{display:block}.record view>text{font-size:21rpx;color:#8c96a7;margin-top:9rpx}</style>
